/* ============================================
   GlobalStone Design System
   ============================================ */

/* CSS Variables */
:root {
  --color-primary: #003F2D;
  --color-secondary: #012A2D;
  --color-accent: #C9A227;
  --color-neutral: #E6E6E6;
  --color-white: #FFFFFF;
  --color-gray-50: #F8F9FA;
  --color-gray-100: #F1F3F5;
  --color-gray-200: #E9ECEF;
  --color-gray-300: #DEE2E6;
  --color-gray-400: #ADB5BD;
  --color-gray-500: #868E96;
  --color-gray-600: #495057;
  --color-gray-700: #343A40;
  --color-gray-800: #212529;
  --color-gray-900: #0A1628;

  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-heading: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;

  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px rgba(0,0,0,0.07), 0 1px 3px rgba(0,0,0,0.06);
  --shadow-lg: 0 10px 25px rgba(0,0,0,0.1), 0 4px 10px rgba(0,0,0,0.05);
  --shadow-xl: 0 20px 40px rgba(0,0,0,0.12), 0 8px 16px rgba(0,0,0,0.08);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--color-gray-700);
  background: var(--color-white);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 600;
  line-height: 1.2;
  color: var(--color-gray-900);
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.5rem); }
h4 { font-size: 1.125rem; }

.text-display {
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.text-lead {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--color-gray-600);
}

.text-sm { font-size: 0.875rem; }
.text-xs { font-size: 0.75rem; }

/* Container */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.container-narrow {
  max-width: 960px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  transition: all var(--transition-base);
  white-space: nowrap;
}

.btn-primary {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn-primary:hover {
  background: var(--color-secondary);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-accent {
  background: var(--color-accent);
  color: var(--color-gray-900);
}

.btn-accent:hover {
  filter: brightness(1.1);
  transform: translateY(-1px);
}

.btn-outline {
  background: transparent;
  color: var(--color-white);
  border: 1.5px solid var(--color-white);
}

.btn-outline:hover {
  background: var(--color-white);
  color: var(--color-gray-900);
}

.btn-outline-dark {
  background: transparent;
  color: var(--color-gray-900);
  border: 1.5px solid var(--color-gray-300);
}

.btn-outline-dark:hover {
  background: var(--color-gray-900);
  color: var(--color-white);
  border-color: var(--color-gray-900);
}

/* Link with arrow */
.link-arrow {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  font-weight: 600;
  font-size: 0.9375rem;
  color: var(--color-primary);
  transition: gap var(--transition-base);
}

.link-arrow:hover {
  gap: var(--space-3);
}

.link-arrow svg {
  width: 16px;
  height: 16px;
}

/* Section spacing */
.section {
  padding: var(--space-20) 0;
}

.section-sm {
  padding: var(--space-12) 0;
}

.section-dark {
  background: var(--color-gray-900);
  color: var(--color-gray-200);
}

.section-dark h1,
.section-dark h2,
.section-dark h3,
.section-dark h4 {
  color: var(--color-white);
}

.section-primary {
  background: var(--color-primary);
  color: var(--color-white);
}

.section-primary h1,
.section-primary h2,
.section-primary h3,
.section-primary h4 {
  color: var(--color-white);
}

/* Section header */
.section-header {
  margin-bottom: var(--space-12);
}

.section-header h2 {
  margin-bottom: var(--space-4);
}

.section-header p {
  max-width: 640px;
  color: var(--color-gray-500);
}

/* Cards */
.card {
  background: var(--color-white);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.card-image {
  aspect-ratio: 16 / 10;
  background: var(--color-gray-200);
  overflow: hidden;
}

.card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-slow);
}

.card:hover .card-image img {
  transform: scale(1.05);
}

.card-body {
  padding: var(--space-6);
}

/* Grid layouts */
.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-8);
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-6);
}

.grid-6 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
}

/* Tags */
.tag {
  display: inline-block;
  padding: var(--space-1) var(--space-3);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: var(--radius-sm);
  background: var(--color-gray-100);
  color: var(--color-gray-600);
}

.tag-accent {
  background: rgba(201, 162, 39, 0.15);
  color: var(--color-accent);
}

/* Overlays */
.overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(10, 22, 40, 0.85) 0%, rgba(10, 22, 40, 0.3) 50%, rgba(10, 22, 40, 0.1) 100%);
}

.overlay-dark {
  background: rgba(10, 22, 40, 0.7);
}

/* ============================================
   HEADER & NAVIGATION
   ============================================ */

.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--color-white);
  border-bottom: 1px solid var(--color-gray-200);
  transition: box-shadow var(--transition-base);
}

.header-scrolled {
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-gray-900);
  letter-spacing: -0.02em;
}

.logo span {
  color: var(--color-primary);
}

.nav-desktop {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.nav-link {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-gray-700);
  padding: var(--space-2) 0;
  position: relative;
  transition: color var(--transition-fast);
}

.nav-link:hover,
.nav-link.active {
  color: var(--color-gray-900);
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--color-primary);
  transition: width var(--transition-base);
}

.nav-link:hover::after,
.nav-link.active::after {
  width: 100%;
}

/* Mega Menu */
.mega-menu-trigger {
  position: relative;
}

.mega-menu {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%) translateY(8px);
  width: 800px;
  max-width: calc(100vw - var(--space-12));
  background: var(--color-white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-xl);
  padding: var(--space-8);
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--transition-base), transform var(--transition-base), visibility var(--transition-base);
  pointer-events: none;
}

.mega-menu-trigger:hover .mega-menu,
.mega-menu-trigger:focus-within .mega-menu {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
  pointer-events: auto;
}

.mega-menu-grid {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: var(--space-8);
}

.mega-menu-title {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-gray-400);
  margin-bottom: var(--space-4);
}

.mega-menu-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.mega-menu-list a {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-gray-700);
  padding: var(--space-2) 0;
  transition: color var(--transition-fast);
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.mega-menu-list a:hover {
  color: var(--color-primary);
}

.mega-menu-list a svg {
  width: 16px;
  height: 16px;
  opacity: 0;
  transform: translateX(-4px);
  transition: all var(--transition-fast);
}

.mega-menu-list a:hover svg {
  opacity: 1;
  transform: translateX(0);
}

/* Mobile nav toggle */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
}

.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-gray-900);
  transition: all var(--transition-base);
}

.nav-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.nav-toggle.active span:nth-child(2) {
  opacity: 0;
}

.nav-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile nav panel */
.nav-mobile {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-white);
  padding: var(--space-6);
  overflow-y: auto;
  z-index: 999;
}

.nav-mobile.active {
  display: block;
}

.mobile-nav-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.mobile-nav-item {
  border-bottom: 1px solid var(--color-gray-200);
}

.mobile-nav-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-4) 0;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--color-gray-900);
}

.mobile-nav-link svg {
  width: 20px;
  height: 20px;
  transition: transform var(--transition-base);
}

.mobile-nav-link[aria-expanded="true"] svg {
  transform: rotate(180deg);
}

.mobile-submenu {
  display: none;
  padding: 0 0 var(--space-4) var(--space-4);
  flex-direction: column;
  gap: var(--space-3);
}

.mobile-submenu.active {
  display: flex;
}

.mobile-submenu a {
  font-size: 0.9375rem;
  color: var(--color-gray-600);
  padding: var(--space-1) 0;
}

.mobile-submenu a:hover {
  color: var(--color-primary);
}

/* ============================================
   HERO
   ============================================ */

.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: flex-end;
  padding-bottom: var(--space-20);
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.hero-bg img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 720px;
}

.hero-title {
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 700;
  line-height: 1.1;
  color: var(--color-white);
  margin-bottom: var(--space-6);
  text-shadow: 0 2px 20px rgba(0,0,0,0.3);
}

.hero-subtitle {
  font-size: 1.125rem;
  line-height: 1.7;
  color: rgba(255,255,255,0.9);
  margin-bottom: var(--space-8);
  max-width: 560px;
}

.hero-actions {
  display: flex;
  gap: var(--space-4);
  flex-wrap: wrap;
}

/* Hero compact (for inner pages) */
.hero-compact {
  min-height: 50vh;
  padding: calc(72px + var(--space-16)) 0 var(--space-16);
  align-items: center;
}

.hero-compact .hero-content {
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}

/* ============================================
   FEATURED INSIGHTS BAR
   ============================================ */

.insights-bar {
  background: var(--color-gray-50);
  border-bottom: 1px solid var(--color-gray-200);
  padding: var(--space-6) 0;
}

.insights-bar-inner {
  display: flex;
  align-items: center;
  gap: var(--space-8);
  flex-wrap: wrap;
}

.insights-bar-label {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-gray-400);
  white-space: nowrap;
}

.insights-bar-list {
  display: flex;
  gap: var(--space-8);
  flex-wrap: wrap;
}

.insights-bar-item {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-gray-700);
  transition: color var(--transition-fast);
}

.insights-bar-item:hover {
  color: var(--color-primary);
}

.insights-bar-item svg {
  width: 18px;
  height: 18px;
  color: var(--color-primary);
  flex-shrink: 0;
}

/* ============================================
   ANNOUNCEMENT BANNER
   ============================================ */

.announcement {
  background: var(--color-secondary);
  color: var(--color-white);
  padding: var(--space-4) 0;
}

.announcement-inner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-6);
  flex-wrap: wrap;
  text-align: center;
}

.announcement-text {
  font-size: 1rem;
  font-weight: 500;
}

.announcement-link {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-accent);
  transition: gap var(--transition-base);
}

.announcement-link:hover {
  gap: var(--space-3);
}

/* ============================================
   ABOUT STATEMENT
   ============================================ */

.about-statement {
  text-align: center;
  max-width: 880px;
  margin: 0 auto;
}

.about-statement h2 {
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: var(--space-8);
  color: var(--color-gray-800);
}

/* ============================================
   WHAT WE DO TABS
   ============================================ */

.tabs-section {
  background: var(--color-gray-50);
}

.tabs-wrapper {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: var(--space-12);
  min-height: 400px;
}

.tabs-nav {
  display: flex;
  flex-direction: column;
  border-left: 2px solid var(--color-gray-200);
}

.tab-btn {
  padding: var(--space-5) var(--space-6);
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--color-gray-500);
  text-align: left;
  border-left: 2px solid transparent;
  margin-left: -2px;
  transition: all var(--transition-base);
  position: relative;
}

.tab-btn:hover {
  color: var(--color-gray-700);
}

.tab-btn.active {
  color: var(--color-primary);
  border-left-color: var(--color-primary);
  background: linear-gradient(to right, rgba(0, 63, 45, 0.04), transparent);
}

.tab-panel {
  display: none;
  animation: fadeIn 0.4s ease;
}

.tab-panel.active {
  display: block;
}

.tab-panel h3 {
  font-size: 1.75rem;
  margin-bottom: var(--space-4);
}

.tab-panel p {
  font-size: 1.0625rem;
  line-height: 1.7;
  color: var(--color-gray-600);
  margin-bottom: var(--space-8);
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateX(12px); }
  to { opacity: 1; transform: translateX(0); }
}

/* ============================================
   NEWSLETTER
   ============================================ */

.newsletter-box {
  background: var(--color-primary);
  border-radius: var(--radius-lg);
  padding: var(--space-12) var(--space-10);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-8);
  flex-wrap: wrap;
}

.newsletter-content h3 {
  font-size: 1.75rem;
  color: var(--color-white);
  margin-bottom: var(--space-2);
}

.newsletter-content p {
  color: rgba(255,255,255,0.8);
}

/* ============================================
   INSIGHTS CARDS
   ============================================ */

.insight-card {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.insight-card .card-image {
  aspect-ratio: 16 / 10;
}

.insight-card .card-body {
  flex: 1;
  display: flex;
  flex-direction: column;
}

.insight-card .tag {
  margin-bottom: var(--space-3);
}

.insight-card h4 {
  font-size: 1.0625rem;
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: var(--space-3);
  color: var(--color-gray-900);
}

.insight-card .date {
  font-size: 0.875rem;
  color: var(--color-gray-400);
  margin-top: auto;
}

/* ============================================
   COMMITMENT PILLARS
   ============================================ */

.pillar-card {
  padding: var(--space-8);
  border-radius: var(--radius-md);
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  transition: all var(--transition-base);
  height: 100%;
}

.pillar-card:hover {
  border-color: var(--color-gray-300);
  box-shadow: var(--shadow-lg);
}

.pillar-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: rgba(0, 63, 45, 0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-5);
}

.pillar-icon svg {
  width: 24px;
  height: 24px;
  color: var(--color-primary);
}

.pillar-card h4 {
  font-size: 1.125rem;
  margin-bottom: var(--space-3);
}

.pillar-card p {
  font-size: 0.9375rem;
  color: var(--color-gray-600);
  line-height: 1.6;
  margin-bottom: var(--space-5);
}

/* ============================================
   SERVICE CARDS
   ============================================ */

.service-card {
  padding: var(--space-8);
  border-radius: var(--radius-md);
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  transition: all var(--transition-base);
  height: 100%;
  display: flex;
  flex-direction: column;
}

.service-card:hover {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-lg);
}

.service-card h4 {
  font-size: 1.25rem;
  margin-bottom: var(--space-3);
}

.service-card p {
  font-size: 0.9375rem;
  color: var(--color-gray-600);
  line-height: 1.6;
  margin-bottom: var(--space-5);
  flex: 1;
}

/* ============================================
   CAPABILITY CARDS
   ============================================ */

.capability-card {
  padding: var(--space-8);
  border-radius: var(--radius-md);
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  transition: all var(--transition-base);
}

.capability-card:hover {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-md);
}

.capability-card h4 {
  font-size: 1.125rem;
  margin-bottom: var(--space-3);
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.capability-card h4 svg {
  width: 20px;
  height: 20px;
  color: var(--color-primary);
  flex-shrink: 0;
}

.capability-card p {
  font-size: 0.9375rem;
  color: var(--color-gray-600);
  line-height: 1.6;
}

/* ============================================
   CAROUSEL
   ============================================ */

.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform var(--transition-slow);
}

.carousel-slide {
  min-width: 100%;
  padding: 0 var(--space-4);
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: var(--space-3);
  margin-top: var(--space-8);
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-gray-300);
  transition: all var(--transition-base);
}

.carousel-dot.active {
  background: var(--color-primary);
  transform: scale(1.2);
}

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-white);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  transition: all var(--transition-base);
}

.carousel-arrow:hover {
  background: var(--color-primary);
  color: var(--color-white);
}

.carousel-arrow.prev { left: var(--space-4); }
.carousel-arrow.next { right: var(--space-4); }

/* ============================================
   TESTIMONIAL
   ============================================ */

.testimonial {
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}

.testimonial blockquote {
  font-size: clamp(1.25rem, 2.5vw, 1.75rem);
  font-weight: 500;
  line-height: 1.5;
  color: var(--color-gray-800);
  margin-bottom: var(--space-8);
  font-style: italic;
}

.testimonial cite {
  font-style: normal;
  font-size: 0.9375rem;
  color: var(--color-gray-500);
}

.testimonial cite strong {
  display: block;
  color: var(--color-gray-900);
  font-weight: 600;
  margin-bottom: var(--space-1);
}

/* ============================================
   FOOTER
   ============================================ */

.footer {
  background: var(--color-gray-900);
  color: var(--color-gray-400);
  padding: var(--space-16) 0 var(--space-8);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: var(--space-12);
  margin-bottom: var(--space-12);
}

.footer-brand .logo {
  color: var(--color-white);
  margin-bottom: var(--space-4);
}

.footer-brand p {
  font-size: 0.9375rem;
  line-height: 1.6;
  max-width: 320px;
}

.footer-col h5 {
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-white);
  margin-bottom: var(--space-5);
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.footer-col a {
  font-size: 0.9375rem;
  color: var(--color-gray-400);
  transition: color var(--transition-fast);
}

.footer-col a:hover {
  color: var(--color-white);
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: var(--space-8);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-4);
}

.footer-bottom p {
  font-size: 0.875rem;
}

.footer-legal {
  display: flex;
  gap: var(--space-6);
  flex-wrap: wrap;
}

.footer-legal a {
  font-size: 0.875rem;
  color: var(--color-gray-500);
  transition: color var(--transition-fast);
}

.footer-legal a:hover {
  color: var(--color-white);
}

/* ============================================
   RESPONSIVE
   ============================================ */

@media (max-width: 1024px) {
  .grid-4 {
    grid-template-columns: repeat(2, 1fr);
  }

  .grid-6 {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .tabs-wrapper {
    grid-template-columns: 1fr;
    gap: var(--space-8);
  }

  .tabs-nav {
    flex-direction: row;
    border-left: none;
    border-bottom: 2px solid var(--color-gray-200);
    overflow-x: auto;
  }

  .tab-btn {
    border-left: none;
    border-bottom: 2px solid transparent;
    margin-left: 0;
    margin-bottom: -2px;
    white-space: nowrap;
    padding: var(--space-4) var(--space-5);
  }

  .tab-btn.active {
    border-left-color: transparent;
    border-bottom-color: var(--color-primary);
    background: none;
  }
}

@media (max-width: 768px) {
  .nav-desktop {
    display: none;
  }

  .nav-toggle {
    display: flex;
  }

  .grid-2,
  .grid-3,
  .grid-4,
  .grid-6 {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: var(--space-8);
  }

  .hero-actions {
    flex-direction: column;
  }

  .btn {
    width: 100%;
  }

  .insights-bar-inner {
    flex-direction: column;
    align-items: flex-start;
  }

  .newsletter-box {
    flex-direction: column;
    text-align: center;
  }

  .section {
    padding: var(--space-12) 0;
  }

  .mega-menu {
    display: none;
  }
}

/* ============================================
   UTILITY
   ============================================ */

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.text-center { text-align: center; }
.text-white { color: var(--color-white); }
.text-primary { color: var(--color-primary); }

.mb-2 { margin-bottom: var(--space-2); }
.mb-4 { margin-bottom: var(--space-4); }
.mb-6 { margin-bottom: var(--space-6); }
.mb-8 { margin-bottom: var(--space-8); }
.mb-12 { margin-bottom: var(--space-12); }

.mt-auto { margin-top: auto; }

edit.old:
.grid-6 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
}

edit.new:
.grid-5 {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-4);
}

.grid-6 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
}
